/// Immutable actor/item names verified from Longshot's inventory header.
///
/// The exact game strings (`Weapon_Sword_Kokiri`, `Item_Ocarina_Fairy`) are
/// what the save stores; [ActorEntry.displayName] is the human label. The
/// catalogue is generated by `tool/gen_catalogues.dart` from
/// `gpu/vk/oot_cheat_items.h` and contains no N64 item ids.
library;

import 'dart:convert';

/// One actor/item row from Longshot's inventory editor.
final class ActorEntry {
  /// Creates an actor entry.
  const ActorEntry({
    required this.name,
    required this.kind,
    required this.displayName,
    required this.labelInferred,
    required this.section,
    required this.stackable,
    required this.sourceLine,
  });

  /// Reads an entry from the generated JSON.
  factory ActorEntry.fromJson(Map<String, Object?> json) {
    return ActorEntry(
      name: _string(json, 'name'),
      kind: _string(json, 'kind'),
      displayName: _string(json, 'displayName'),
      labelInferred: _bool(json, 'labelInferred'),
      section: _string(json, 'section'),
      stackable: _bool(json, 'stackable'),
      sourceLine: _int(json, 'sourceLine'),
    );
  }

  /// The exact game string stored by the save, such as `Weapon_Sword_Kokiri`.
  final String name;

  /// Coarse category: sword, shield, tunic, boots, mask, item, upgrade, quest,
  /// song or bottle.
  final String kind;

  /// Human label. When [labelInferred] is true this was derived from [name].
  final String displayName;

  /// Whether [displayName] was inferred rather than read from a cited label.
  final bool labelInferred;

  /// The source `OOT_SECTION` heading.
  final String section;

  /// Whether the header marks the row as a quantity (its kind is 1).
  final bool stackable;

  /// One-based line in `gpu/vk/oot_cheat_items.h`.
  final int sourceLine;

  @override
  String toString() => 'ActorEntry($name, $displayName)';
}

/// The verified actor/item name catalogue.
final class ActorCatalogue {
  /// Creates a catalogue and rejects duplicate game strings.
  ActorCatalogue({
    required Map<String, Object?> provenance,
    required Iterable<ActorEntry> equipment,
    required Iterable<ActorEntry> items,
    required Iterable<ActorEntry> songs,
    required Iterable<ActorEntry> bottles,
  }) : provenance = _freezeMap(provenance),
       equipment = List<ActorEntry>.unmodifiable(equipment),
       items = List<ActorEntry>.unmodifiable(items),
       songs = List<ActorEntry>.unmodifiable(songs),
       bottles = List<ActorEntry>.unmodifiable(bottles) {
    final byName = <String, ActorEntry>{};
    final all = <ActorEntry>[
      ...this.equipment,
      ...this.items,
      ...this.songs,
      ...this.bottles,
    ];
    for (final entry in all) {
      if (byName.containsKey(entry.name)) {
        throw FormatException('duplicate actor name: ${entry.name}');
      }
      byName[entry.name] = entry;
    }
    _byName = Map<String, ActorEntry>.unmodifiable(byName);
    _all = List<ActorEntry>.unmodifiable(all);
    _equipmentByName = Map<String, ActorEntry>.unmodifiable(
      <String, ActorEntry>{
        for (final entry in this.equipment) entry.name: entry,
      },
    );
  }

  /// Reads a catalogue from already-decoded JSON.
  factory ActorCatalogue.fromJson(Map<String, Object?> json) {
    List<ActorEntry> bucket(String key) => _objectList(
      json[key],
      key,
    ).map(ActorEntry.fromJson).toList(growable: false);
    return ActorCatalogue(
      provenance: _object(json['provenance'], 'provenance'),
      equipment: bucket('equipment'),
      items: bucket('items'),
      songs: bucket('songs'),
      bottles: bucket('bottles'),
    );
  }

  /// Provenance and citation record from the asset.
  final Map<String, Object?> provenance;

  /// Swords, shields, tunics, boots and masks.
  final List<ActorEntry> equipment;

  /// Items, upgrades and quest rows that are not songs or bottles.
  final List<ActorEntry> items;

  /// The twelve `Item_Melody_*` rows.
  final List<ActorEntry> songs;

  /// The `Item_Bottle` row.
  final List<ActorEntry> bottles;

  late final List<ActorEntry> _all;
  late final Map<String, ActorEntry> _byName;
  late final Map<String, ActorEntry> _equipmentByName;

  /// All 86 entries, grouped equipment, items, songs, bottles.
  List<ActorEntry> get all => _all;

  /// Looks up any actor/item by its exact game string.
  ActorEntry? byName(String name) => _byName[name];

  /// Resolves an exact equipment game string, or `null` for anything else.
  ///
  /// The strict game-name shape (letters, digits, underscores) and exact
  /// membership reject SQL fragments and other junk even before lookup.
  ActorEntry? withEquipment(String name) {
    if (!_gameName.hasMatch(name) || name.length > 96) {
      return null;
    }
    return _equipmentByName[name];
  }

  /// Whether [name] is an exact, well-formed equipment string in the catalogue.
  bool isValidEquipmentString(String name) => withEquipment(name) != null;

  /// Whether [name] is an exact, well-formed game string in any bucket.
  bool isValidActorString(String name) {
    if (!_gameName.hasMatch(name) || name.length > 96) {
      return false;
    }
    return _byName.containsKey(name);
  }

  /// Human labels for [kind].
  ///
  /// [kind] may be a bucket name (`equipment`, `items`, `songs`, `bottles`) or
  /// an entry kind (`sword`, `shield`, `mask`, `song`, ...). Matching is
  /// case-insensitive and the result is sorted.
  List<String> labelsFor(String kind) {
    final normalized = kind.toLowerCase();
    final Iterable<ActorEntry> source = switch (normalized) {
      'equipment' => equipment,
      'items' => items,
      'songs' => songs,
      'bottles' => bottles,
      _ => _all.where((entry) => entry.kind.toLowerCase() == normalized),
    };
    final labels = source.map((entry) => entry.displayName).toList()..sort();
    return List<String>.unmodifiable(labels);
  }

  /// Case- and diacritic-insensitive substring search over names and labels.
  List<ActorEntry> search(String query) {
    final needle = _fold(query);
    final matches = <ActorEntry>[
      for (final entry in _all)
        if (_fold(entry.name).contains(needle) ||
            _fold(entry.displayName).contains(needle))
          entry,
    ];
    matches.sort((a, b) {
      final byDisplay = _fold(a.displayName).compareTo(_fold(b.displayName));
      return byDisplay != 0 ? byDisplay : a.name.compareTo(b.name);
    });
    return List<ActorEntry>.unmodifiable(matches);
  }

  @override
  String toString() =>
      'ActorCatalogue(${equipment.length} equipment, ${items.length} items, '
      '${songs.length} songs, ${bottles.length} bottles)';
}

/// Loads a catalogue from the JSON text of `assets/catalogue/actors.json`.
ActorCatalogue loadActorCatalogue(String source) {
  final decoded = jsonDecode(source);
  if (decoded is! Map<String, Object?>) {
    throw const FormatException('actor catalogue: expected a JSON object');
  }
  return ActorCatalogue.fromJson(decoded);
}

final RegExp _gameName = RegExp(r'^[A-Za-z][A-Za-z0-9_]*$');

Map<String, Object?> _object(Object? value, String label) {
  if (value is! Map<String, Object?>) {
    throw FormatException('$label: expected an object');
  }
  return value;
}

List<Map<String, Object?>> _objectList(Object? value, String label) {
  if (value is! List<Object?>) {
    throw FormatException('$label: expected a list');
  }
  return <Map<String, Object?>>[
    for (final entry in value)
      if (entry is Map<String, Object?>)
        entry
      else
        throw FormatException('$label: expected an object in the list'),
  ];
}

String _string(Map<String, Object?> json, String key) {
  final value = json[key];
  if (value is! String) {
    throw FormatException('$key: expected a string');
  }
  return value;
}

bool _bool(Map<String, Object?> json, String key) {
  final value = json[key];
  if (value is! bool) {
    throw FormatException('$key: expected a boolean');
  }
  return value;
}

int _int(Map<String, Object?> json, String key) {
  final value = json[key];
  if (value is! int) {
    throw FormatException('$key: expected an integer');
  }
  return value;
}

Map<String, Object?> _freezeMap(Map<String, Object?> source) {
  return Map<String, Object?>.unmodifiable(<String, Object?>{
    for (final entry in source.entries) entry.key: _freeze(entry.value),
  });
}

Object? _freeze(Object? value) {
  if (value is Map<String, Object?>) {
    return _freezeMap(value);
  }
  if (value is List<Object?>) {
    return List<Object?>.unmodifiable(<Object?>[
      for (final entry in value) _freeze(entry),
    ]);
  }
  return value;
}

String _fold(String value) {
  final lower = value.toLowerCase();
  final buffer = StringBuffer();
  for (final rune in lower.runes) {
    final character = String.fromCharCode(rune);
    buffer.write(_diacritics[character] ?? character);
  }
  return buffer.toString();
}

